"use client";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ComponentProps,
  type KeyboardEvent,
  type ReactNode,
  type Ref,
} from "react";
import { Search, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { assignRef, useLiquidElement } from "@/lib/liquid/motion";
import { useLiquidRefraction } from "@/lib/liquid/refraction";
import { useTabBarMorph } from "@/lib/liquid/tab-bar";
import "./liquid.css";

type TabBarState = { searching: boolean; setSearching: (searching: boolean) => void };

const TabBarContext = createContext<TabBarState>({ searching: false, setSearching: () => {} });

export type TabBarProps = ComponentProps<"div"> & {
  /** Whether search is open. Leave undefined to let the tab bar manage it. */
  searching?: boolean;
  defaultSearching?: boolean;
  onSearchingChange?: (searching: boolean) => void;
};

/**
 * A floating tab bar with a search button beside it, as in iOS 26. Opening search collapses
 * the tabs into a circle and stretches the button into a field.
 */
export function TabBar({
  searching: controlled,
  defaultSearching = false,
  onSearchingChange,
  className,
  ref,
  ...props
}: TabBarProps) {
  const [node, mergedRef] = useLiquidElement(ref);
  const [uncontrolled, setUncontrolled] = useState(defaultSearching);
  const searching = controlled ?? uncontrolled;
  const setSearching = useCallback(
    (next: boolean) => {
      setUncontrolled(next);
      onSearchingChange?.(next);
    },
    [onSearchingChange],
  );
  const value = useMemo(() => ({ searching, setSearching }), [searching, setSearching]);
  useTabBarMorph(node, searching);
  return (
    <TabBarContext.Provider value={value}>
      <div
        ref={mergedRef}
        className={cn("liquid-tab-bar", className)}
        data-searching={searching ? "" : undefined}
        {...props}
      />
    </TabBarContext.Provider>
  );
}

export type TabBarItemsProps = ComponentProps<"div"> & {
  /** Shown in the circle the tabs collapse into, usually the selected tab's icon. */
  icon?: ReactNode;
  /** Accessible name of that circle, which closes search. */
  label?: string;
};

/** The glass around the tabs. Put a liquid `TabsList` (or any list of links) inside. */
export function TabBarItems({
  icon,
  label = "Show tabs",
  className,
  children,
  ref,
  ...props
}: TabBarItemsProps) {
  const { searching, setSearching } = useContext(TabBarContext);
  const [node, mergedRef] = useLiquidElement(ref);
  useLiquidRefraction(node);
  return (
    <div
      ref={mergedRef}
      className={cn("liquid-surface liquid-tab-bar-items", className)}
      {...props}
    >
      <div className="liquid-tab-bar-tabs" inert={searching} aria-hidden={searching || undefined}>
        {children}
      </div>
      {searching && (
        <button
          type="button"
          className="liquid-tab-bar-restore"
          aria-label={label}
          onClick={() => setSearching(false)}
        >
          {icon}
        </button>
      )}
    </div>
  );
}

/**
 * Focus the field when search opens, and the search button when it closes from inside. Returns
 * the field's ref, merged with the consumer's, and the search button's ref.
 */
function useSearchFocus(searching: boolean, root: HTMLElement | null, ref?: Ref<HTMLInputElement>) {
  const fieldRef = useRef<HTMLInputElement | null>(null);
  const toggleRef = useRef<HTMLButtonElement | null>(null);
  const previousRef = useRef(searching);
  useEffect(() => {
    if (previousRef.current === searching) return;
    previousRef.current = searching;
    const active = document.activeElement;
    if (searching) fieldRef.current?.focus();
    else if (!active || active === document.body || root?.contains(active))
      toggleRef.current?.focus();
  }, [searching, root]);
  const inputRef = useCallback(
    (element: HTMLInputElement | null) => {
      fieldRef.current = element;
      return assignRef(ref, element);
    },
    [ref],
  );
  return { inputRef, toggleRef };
}

export type TabBarSearchProps = ComponentProps<"input"> & {
  /** Accessible name of the button that closes search. */
  closeLabel?: string;
};

/**
 * The search button, which becomes the search field. Props, ref, and events go to the
 * `<input>`, except `className`, which styles the glass.
 */
export function TabBarSearch({
  className,
  placeholder = "Search",
  closeLabel = "Close search",
  "aria-label": label = "Search",
  onKeyDown,
  ref,
  ...props
}: TabBarSearchProps) {
  const { searching, setSearching } = useContext(TabBarContext);
  const [node, surfaceRef] = useLiquidElement<HTMLDivElement>();
  useLiquidRefraction(node);
  const { inputRef, toggleRef } = useSearchFocus(searching, node?.parentElement ?? null, ref);
  const keyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    onKeyDown?.(event);
    if (event.key !== "Escape" || event.defaultPrevented) return;
    event.preventDefault();
    setSearching(false);
  };
  return (
    <div
      ref={surfaceRef}
      className={cn("liquid-surface liquid-interactive liquid-tab-bar-search", className)}
    >
      {searching ? (
        <>
          <Search aria-hidden="true" className="liquid-tab-bar-glass" />
          <input
            ref={inputRef}
            type="search"
            enterKeyHint="search"
            placeholder={placeholder}
            aria-label={label}
            onKeyDown={keyDown}
            {...props}
          />
          <button
            type="button"
            className="liquid-tab-bar-close"
            aria-label={closeLabel}
            onClick={() => setSearching(false)}
          >
            <X aria-hidden="true" />
          </button>
        </>
      ) : (
        <button
          ref={toggleRef}
          type="button"
          className="liquid-tab-bar-toggle"
          aria-label={label}
          onClick={() => setSearching(true)}
        >
          <Search aria-hidden="true" />
        </button>
      )}
    </div>
  );
}

"use client";
import type { ComponentProps } from "react";
import { TabsList as BaseList, TabsTrigger as BaseTrigger } from "@/components/ui/tabs";
import { cn } from "@/lib/utils";
import { useLiquidElement } from "@/lib/liquid/motion";
import { useLiquidIndicator } from "@/lib/liquid/lens";
import { useLiquidRefraction } from "@/lib/liquid/refraction";
import "./liquid.css";
export { Tabs, TabsContent } from "@/components/ui/tabs";
export function TabsList({ className, ref, ...props }: ComponentProps<typeof BaseList>) {
  const [node, mergedRef] = useLiquidElement(ref);
  useLiquidIndicator(node, {
    selected: '.liquid-tab[data-state="active"]',
    items: ".liquid-tab",
    scrub: true,
  });
  useLiquidRefraction(node);
  return (
    <BaseList ref={mergedRef} className={cn("liquid-surface liquid-tabs", className)} {...props} />
  );
}
export function TabsTrigger({ className, ...props }: ComponentProps<typeof BaseTrigger>) {
  return <BaseTrigger className={cn("liquid-tab", className)} {...props} />;
}

"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Tabs as TabsPrimitive } from "radix-ui";

function Tabs({
  className,
  orientation = "horizontal",
  ...props
}: React.ComponentProps<typeof TabsPrimitive.Root>) {
  return (
    <TabsPrimitive.Root
      data-slot="tabs"
      data-orientation={orientation}
      orientation={orientation}
      className={cn("group/tabs flex gap-2 data-[orientation=horizontal]:flex-col", className)}
      {...props}
    />
  );
}

const tabsListVariants = cva(
  "group/tabs-list inline-flex w-fit items-center justify-center rounded-lg p-[3px] text-muted-foreground group-data-[orientation=horizontal]/tabs:h-9 group-data-[orientation=vertical]/tabs:h-fit group-data-[orientation=vertical]/tabs:flex-col data-[variant=line]:rounded-none",
  {
    variants: {
      variant: {
        default: "bg-muted",
        line: "gap-1 bg-transparent",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

function TabsList({
  className,
  variant = "default",
  ...props
}: React.ComponentProps<typeof TabsPrimitive.List> & VariantProps<typeof tabsListVariants>) {
  return (
    <TabsPrimitive.List
      data-slot="tabs-list"
      data-variant={variant}
      className={cn(tabsListVariants({ variant }), className)}
      {...props}
    />
  );
}

function TabsTrigger({ className, ...props }: React.ComponentProps<typeof TabsPrimitive.Trigger>) {
  return (
    <TabsPrimitive.Trigger
      data-slot="tabs-trigger"
      className={cn(
        "relative inline-flex h-[calc(100%-1px)] flex-1 items-center justify-center gap-1.5 rounded-md border border-transparent px-2 py-1 text-sm font-medium whitespace-nowrap text-foreground/60 transition-all group-data-[orientation=vertical]/tabs:w-full group-data-[orientation=vertical]/tabs:justify-start hover:text-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:outline-1 focus-visible:outline-ring disabled:pointer-events-none disabled:opacity-50 group-data-[variant=default]/tabs-list:data-[state=active]:shadow-sm group-data-[variant=line]/tabs-list:data-[state=active]:shadow-none dark:text-muted-foreground dark:hover:text-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        "group-data-[variant=line]/tabs-list:bg-transparent group-data-[variant=line]/tabs-list:data-[state=active]:bg-transparent dark:group-data-[variant=line]/tabs-list:data-[state=active]:border-transparent dark:group-data-[variant=line]/tabs-list:data-[state=active]:bg-transparent",
        "data-[state=active]:bg-background data-[state=active]:text-foreground dark:data-[state=active]:border-input dark:data-[state=active]:bg-input/30 dark:data-[state=active]:text-foreground",
        "after:absolute after:bg-foreground after:opacity-0 after:transition-opacity group-data-[orientation=horizontal]/tabs:after:inset-x-0 group-data-[orientation=horizontal]/tabs:after:bottom-[-5px] group-data-[orientation=horizontal]/tabs:after:h-0.5 group-data-[orientation=vertical]/tabs:after:inset-y-0 group-data-[orientation=vertical]/tabs:after:-right-1 group-data-[orientation=vertical]/tabs:after:w-0.5 group-data-[variant=line]/tabs-list:data-[state=active]:after:opacity-100",
        className,
      )}
      {...props}
    />
  );
}

function TabsContent({ className, ...props }: React.ComponentProps<typeof TabsPrimitive.Content>) {
  return (
    <TabsPrimitive.Content
      data-slot="tabs-content"
      className={cn("flex-1 outline-none", className)}
      {...props}
    />
  );
}

export { Tabs, TabsList, TabsTrigger, TabsContent, tabsListVariants };

/* Material defaults live on the root, so a value set on any ancestor reaches its glass. */
:root {
  --liquid-blur: 20px;
  --liquid-tint: 0.22;
  --liquid-ink: #172323;
  --liquid-fill: 255 255 255;
}
.liquid-surface {
  position: relative;
  color: var(--liquid-ink);
  background: rgb(var(--liquid-fill) / var(--liquid-tint));
  border: 1px solid rgb(255 255 255 / 0.65);
  -webkit-backdrop-filter: blur(var(--liquid-blur)) saturate(1.7);
  backdrop-filter: blur(var(--liquid-blur)) saturate(1.7);
  box-shadow:
    inset 0 1px 1px rgb(255 255 255 / 0.9),
    inset 0 -1px 1px rgb(255 255 255 / 0.25),
    inset 2px 0 5px rgb(255 255 255 / 0.18),
    0 8px 28px rgb(0 20 25 / 0.14);
  transition:
    background 200ms ease,
    box-shadow 200ms ease;
}
/* No focus rings. Keyboard focus tints the glass instead, so it stays visible without one. */
.liquid-surface:focus-visible,
.liquid-tab:focus-visible,
.liquid-toolbar-button:focus-visible,
.liquid-tab-bar :is(button, input):focus-visible {
  outline: none;
}
.liquid-surface:not(.liquid-interactive, [role="menu"], [role="dialog"]):focus-visible {
  background-color: rgb(var(--liquid-fill) / calc(var(--liquid-tint) + 0.2));
}
.liquid-interactive {
  position: relative;
  translate: var(--liquid-x, 0px) var(--liquid-y, 0px);
  scale: var(--liquid-scale-x, 1) var(--liquid-scale-y, 1);
  /* The spring owns translate/scale; consumers still own transform. */
  transition:
    background 200ms ease,
    box-shadow 200ms ease,
    opacity 140ms ease;
}
/* Keyboard focus tints the glass, like a highlighted menu item. */
.liquid-interactive:is(:focus-visible, :has(> .liquid-tab-bar-toggle:focus-visible)):not(
    [data-liquid-variant="prominent"]
  ) {
  background-color: color-mix(
    in srgb,
    var(--liquid-accent, #007aff) 18%,
    rgb(var(--liquid-fill) / max(var(--liquid-tint), 0.3))
  );
}
/* Content morph: new content condenses out of light while the width springs. */
.liquid-interactive[data-liquid-morphing] {
  overflow: clip;
}
.liquid-interactive[data-liquid-morph="a"] {
  animation: liquid-ink-in-a 420ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.liquid-interactive[data-liquid-morph="b"] {
  animation: liquid-ink-in-b 420ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.liquid-interactive[data-liquid-morph="a"] > svg {
  animation: liquid-glyph-in-a 480ms cubic-bezier(0.2, 0.9, 0.25, 1.25);
}
.liquid-interactive[data-liquid-morph="b"] > svg {
  animation: liquid-glyph-in-b 480ms cubic-bezier(0.2, 0.9, 0.25, 1.25);
}
@keyframes liquid-ink-in-a {
  from {
    color: transparent;
    text-shadow: 0 0 12px rgb(255 255 255 / 0.95);
  }
}
@keyframes liquid-ink-in-b {
  from {
    color: transparent;
    text-shadow: 0 0 12px rgb(255 255 255 / 0.95);
  }
}
@keyframes liquid-glyph-in-a {
  from {
    opacity: 0;
    filter: blur(5px);
    scale: 0.45;
  }
}
@keyframes liquid-glyph-in-b {
  from {
    opacity: 0;
    filter: blur(5px);
    scale: 0.45;
  }
}
.liquid-button {
  border-radius: 999px;
  min-height: 44px;
  font-weight: 600;
  padding-inline: 24px;
}
.liquid-button:hover:not(:disabled) {
  background: rgb(var(--liquid-fill) / calc(var(--liquid-tint) + 0.1));
  box-shadow:
    inset 0 1px 2px white,
    inset 0 -1px 2px rgb(190 224 255 / 0.5),
    0 8px 28px rgb(0 20 25 / 0.14);
}
.liquid-button[data-size^="icon"] {
  padding-inline: 0;
  min-width: 44px;
}
.liquid-button[data-liquid-variant="destructive"] {
  --liquid-ink: #a20c22;
  --liquid-fill: 255 200 208;
}
.liquid-button[data-liquid-variant="link"] {
  text-decoration: underline;
}
.liquid-button[data-liquid-variant="secondary"] {
  background: rgb(var(--liquid-fill) / 0.55);
}
.liquid-button[data-state="open"] > svg {
  rotate: 180deg;
}
.liquid-button > svg {
  transition: rotate 350ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

/* Segmented tabs and toolbars share one lens. */
.liquid-tabs {
  border-radius: 999px;
  padding: 5px;
  height: 52px;
  gap: 3px;
  isolation: isolate;
  touch-action: pan-y;
  -webkit-user-select: none;
  user-select: none;
  -webkit-touch-callout: none;
  transition:
    background 200ms ease,
    box-shadow 200ms ease,
    scale 460ms cubic-bezier(0.25, 1.45, 0.45, 1);
}
.liquid-tabs[data-orientation="vertical"] {
  height: auto;
  border-radius: 26px;
  touch-action: pan-x;
}
/* The whole bar swells a little while a finger is on it. */
.liquid-tabs[data-liquid-pressed] {
  scale: 1.025;
  transition-duration: 200ms, 200ms, 240ms;
}
.liquid-tab {
  position: relative;
  color: var(--liquid-ink);
  /* The base trigger borders the active tab in dark mode, and ahead of the travelling lens. */
  border-color: transparent;
  border-radius: 999px;
  padding-inline: 22px;
  height: 40px;
  background: transparent;
  transition: color 180ms ease;
}
.liquid-tab[data-state="active"] {
  color: var(--liquid-ink);
  background: rgb(var(--liquid-fill) / 0.58);
  box-shadow: inset 0 1px 1px rgb(255 255 255 / 0.8);
}
.liquid-tabs[data-liquid-indicator] .liquid-tab[data-state="active"] {
  background: transparent;
  box-shadow: none;
}
.liquid-tab:hover:not(:disabled) {
  color: var(--liquid-ink);
}
/* The base tabs draw a ring on focus; glass has none. */
.liquid-tab:focus-visible:not([data-state="active"]) {
  box-shadow: none;
  background: rgb(var(--liquid-fill) / 0.3);
}
/* An iOS tab bar: add `liquid-tabbar` to a TabsList to stack icons over labels. */
.liquid-tabbar {
  height: 66px;
  padding: 5px;
  gap: 0;
}
.liquid-tabbar .liquid-tab {
  height: 54px;
  min-width: 88px;
  flex-direction: column;
  gap: 3px;
  padding-inline: 14px;
  font-size: 11px;
  font-weight: 600;
}
.liquid-tabbar .liquid-tab svg {
  width: 23px;
  height: 23px;
}
.liquid-lens {
  position: absolute;
  left: 0;
  top: 0;
  z-index: 1;
  overflow: hidden;
  border-radius: 999px;
  pointer-events: none;
  /* At rest: a frosted pill. Lifted: clear glass with a bright, faintly chromatic rim. */
  background:
    linear-gradient(
      135deg,
      rgb(255 255 255 / calc(0.2 * (1 - var(--liquid-lift, 0)))),
      transparent 55%
    ),
    rgb(
      var(--liquid-lens-fill, 255 255 255) /
        calc(var(--liquid-lens-alpha, 0.5) * (1 - 0.8 * var(--liquid-lift, 0)))
    );
  box-shadow:
    inset 0 1px 1.5px rgb(255 255 255 / calc(0.75 + 0.25 * var(--liquid-lift, 0))),
    inset 0 -1px 1.5px rgb(255 255 255 / calc(0.25 + 0.5 * var(--liquid-lift, 0))),
    inset 2px 0 3px -1px rgb(255 110 190 / calc(0.55 * var(--liquid-lift, 0))),
    inset -2px 0 3px -1px rgb(70 200 255 / calc(0.55 * var(--liquid-lift, 0)));
  opacity: 0;
  transition: opacity 200ms ease;
}
[data-liquid-indicator] > .liquid-lens {
  opacity: 1;
}
/* Focus on the selected item tints the lens over it. */
[data-liquid-indicator]:has(
    > :is([data-state="active"], [aria-pressed="true"], [aria-current]):focus-visible
  )
  > .liquid-lens {
  --liquid-lens-fill: 0 122 255;
  --liquid-lens-alpha: 0.2;
}
/* An inert copy of the list, magnified and tinted inside the lens. */
.liquid-lens > .liquid-lens-optics {
  position: absolute;
  left: 0;
  top: 0;
  margin: 0;
  color: var(--liquid-lens-ink, var(--liquid-accent, var(--liquid-system-accent, #007aff)));
  /* The copy carries the list's classes; strip its material, whichever rule set it. */
  background: none !important;
  border-color: transparent !important;
  box-shadow: none !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  text-shadow: none;
  translate: none;
  scale: none;
  transition: none;
  animation: none;
  pointer-events: none;
}
.liquid-lens-optics * {
  color: inherit !important;
  text-shadow: none !important;
  transition: none !important;
  animation: none !important;
}
.liquid-lens-optics > * {
  background: transparent !important;
  box-shadow: none !important;
  border-color: transparent !important;
  translate: none !important;
  scale: none !important;
}
/* Once the lens has landed the copy stands in for the selected label. */
[data-liquid-lens="rest"]
  :is(.liquid-tab[data-state="active"], .liquid-toolbar-button[aria-pressed="true"]):not(
    .liquid-lens *
  ) {
  color: transparent;
  text-shadow: none;
}
.liquid-menu {
  --liquid-menu-x: 0px;
  --liquid-menu-y: -10px;
  --liquid-menu-scale-x: 0.8;
  --liquid-menu-scale-y: 0.6;
  --liquid-menu-radius: 70px;
  --liquid-menu-mid-x: 0px;
  --liquid-menu-mid-y: -5px;
  --liquid-menu-mid-scale-x: 0.7;
  --liquid-menu-mid-scale-y: 0.7;
  border-radius: 22px;
  padding: 6px;
  min-width: 220px;
  background: rgb(var(--liquid-fill) / max(var(--liquid-tint), 0.68));
  transform-origin: center;
  transition: background 200ms ease;
  /*
   * The panel clips and its body scrolls. The body arrives magnified as the panel forms; were
   * the panel the scroller, that growth would flash scrollbars during every entrance.
   */
  overflow: hidden;
}
.liquid-menu [role^="menuitem"] {
  min-height: 40px;
  border-radius: 15px;
  color: inherit;
  transition: background 140ms ease;
}
.liquid-menu [role^="menuitem"][data-highlighted] {
  background: rgb(0 122 255 / 0.16);
}
.liquid-menu [data-variant="destructive"] {
  color: #c52238;
}
.liquid-menu-body {
  transform-origin: 50% 40%;
  /* The panel's available height, less its padding and border. */
  max-height: calc(var(--radix-dropdown-menu-content-available-height, 100dvh) - 14px);
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
}
.liquid-menu[data-state="open"]:not([data-liquid-morph="ready"]) {
  opacity: 0;
}
.liquid-menu[data-state="open"][data-liquid-morph="ready"] {
  animation: liquid-menu-unfold var(--liquid-morph-duration, 520ms) both;
}
.liquid-menu[data-state="open"][data-liquid-morph="ready"] > .liquid-menu-body {
  animation: liquid-menu-body-in var(--liquid-morph-duration, 520ms) both;
}
.liquid-menu[data-state="closed"] {
  animation: liquid-menu-fold 320ms both;
  pointer-events: none;
}
.liquid-menu[data-state="closed"] > .liquid-menu-body {
  animation: liquid-menu-body-out 130ms ease-in both;
}
/* The trigger swells into a round droplet, which stretches into the panel. */
@keyframes liquid-menu-unfold {
  0% {
    opacity: 0.7;
    transform: translate(var(--liquid-menu-x), var(--liquid-menu-y))
      scale(var(--liquid-menu-scale-x), var(--liquid-menu-scale-y));
    border-radius: var(--liquid-menu-radius);
    animation-timing-function: cubic-bezier(0.3, 0.1, 0.5, 1);
  }
  26% {
    opacity: 1;
    transform: translate(var(--liquid-menu-mid-x), var(--liquid-menu-mid-y))
      scale(var(--liquid-menu-mid-scale-x), var(--liquid-menu-mid-scale-y));
    border-radius: 50%;
    animation-timing-function: cubic-bezier(0.2, 0.7, 0.3, 1);
  }
  62% {
    opacity: 1;
    transform: translate(0, 0) scale(1.025, 1.04);
    border-radius: 22px;
    animation-timing-function: cubic-bezier(0.3, 0, 0.3, 1);
  }
  100% {
    opacity: 1;
    transform: translate(0, 0) scale(1);
    border-radius: 22px;
  }
}
/* Content arrives magnified and out of focus, as if seen through the forming lens. */
@keyframes liquid-menu-body-in {
  0%,
  16% {
    opacity: 0;
    transform: scale(1.3);
    filter: blur(10px);
    animation-timing-function: cubic-bezier(0.2, 0.7, 0.3, 1);
  }
  55% {
    opacity: 1;
    transform: scale(1.05);
    filter: blur(1.5px);
  }
  100% {
    opacity: 1;
    transform: none;
    filter: none;
  }
}
@keyframes liquid-menu-body-out {
  to {
    opacity: 0;
    transform: scale(0.94);
    filter: blur(6px);
  }
}
/* The panel collapses into a droplet that is drawn back into its trigger. */
