"use client";

import { useCallback, useState, type Ref } from "react";

export type LiquidSpring = ReturnType<typeof createLiquidSpring>;

/** A small, interruptible spring. Values stay outside React's render cycle. */
export function createLiquidSpring(
  initial: number[],
  render: (values: number[], velocity: number[]) => void,
) {
  let values = [...initial];
  let target = [...initial];
  const velocity = initial.map(() => 0);
  let frame = 0;
  let previous = 0;
  let viscosity = 0.5;
  const atRest = () =>
    values.every((value, i) => value === target[i]) && velocity.every((speed) => speed === 0);
  const start = () => {
    if (frame) return;
    previous = performance.now();
    frame = requestAnimationFrame(tick);
  };

  function step(dt: number) {
    const steps = Math.max(1, Math.ceil(dt * 240));
    const h = dt / steps;
    const stiffness = 440 - viscosity * 180;
    const damping = 23 + viscosity * 15;
    for (let n = 0; n < steps; n++) {
      values.forEach((value, i) => {
        velocity[i] += (stiffness * (target[i] - value) - damping * velocity[i]) * h;
        values[i] += velocity[i] * h;
      });
    }
  }

  function tick(time: number) {
    // A frame's timestamp can precede the input event that scheduled it. Integrating a
    // negative step would run the spring backwards; a small step still answers the touch.
    step(time > previous ? Math.min((time - previous) / 1000, 0.032) : 1 / 120);
    previous = time;
    const settled = values.every(
      (value, i) => Math.abs(target[i] - value) < 0.001 && Math.abs(velocity[i]) < 0.01,
    );
    if (settled) {
      values = [...target];
      velocity.fill(0);
    }
    frame = 0;
    render(values, velocity);
    // render may retarget the spring, e.g. when a travelling lens lands.
    if (!atRest()) start();
  }

  return {
    to(next: number[], immediate = false, feel = 0.5) {
      target = [...next];
      viscosity = Math.max(0, Math.min(1, feel));
      if (!immediate) {
        if (!atRest()) start();
        return;
      }
      cancelAnimationFrame(frame);
      frame = 0;
      values = [...target];
      velocity.fill(0);
      render(values, velocity);
    },
    /** Add velocity without moving the target, for a pop or a nudge. */
    kick(impulse: number[]) {
      impulse.forEach((speed, i) => {
        velocity[i] += speed;
      });
      start();
    },
    stop() {
      cancelAnimationFrame(frame);
      frame = 0;
    },
  };
}

/** iOS-style rubber band: follows the finger at first, then resists. */
export function rubberBand(distance: number, limit: number) {
  return Math.sign(distance) * limit * (1 - 1 / ((Math.abs(distance) * 0.55) / limit + 1));
}

export function motionReduced(node: HTMLElement) {
  return (
    window.matchMedia("(prefers-reduced-motion: reduce)").matches ||
    !!node.closest('[data-reduced-motion="true"]')
  );
}

export function liquidViscosity(node: HTMLElement) {
  const value = parseFloat(getComputedStyle(node).getPropertyValue("--liquid-viscosity"));
  return Number.isFinite(value) ? Math.max(0, Math.min(1, value)) : 0.5;
}

// Listen to OS preferences and explicit opt-outs, including ancestors of portals.
export function observeMotion(node: HTMLElement, update: () => void) {
  const media = window.matchMedia("(prefers-reduced-motion: reduce)");
  media.addEventListener("change", update);
  const observer = new MutationObserver(update);
  for (let ancestor: HTMLElement | null = node; ancestor; ancestor = ancestor.parentElement) {
    observer.observe(ancestor, { attributes: true, attributeFilter: ["data-reduced-motion"] });
  }
  return () => {
    media.removeEventListener("change", update);
    observer.disconnect();
  };
}

/** Add listeners and get one function that removes them all. */
export function listen(
  target: EventTarget,
  handlers: Record<string, (event: never) => void>,
  options?: AddEventListenerOptions,
) {
  const entries = Object.entries(handlers) as [string, EventListener][];
  entries.forEach(([type, handler]) => target.addEventListener(type, handler, options));
  return () =>
    entries.forEach(([type, handler]) => target.removeEventListener(type, handler, options));
}

/** Hand an element to a forwarded ref of either kind; returns the matching cleanup. */
export function assignRef<T>(ref: Ref<T> | undefined, element: T | null): () => void {
  if (typeof ref === "function") {
    const cleanup = ref(element);
    return () => {
      if (typeof cleanup === "function") cleanup();
      else ref(null);
    };
  }
  if (!ref) return () => {};
  ref.current = element;
  return () => {
    ref.current = null;
  };
}

/**
 * Compose forwarded refs, including React 19 ref cleanups. React calls a ref's cleanup instead
 * of passing it null, so the cleanup clears the node: effects on it then end when the element
 * goes, even if the component stays, as a menu panel does when Radix unmounts it on close.
 */
export function useLiquidElement<T extends HTMLElement>(forwardedRef?: Ref<T>) {
  const [node, setNode] = useState<T | null>(null);
  const ref = useCallback(
    (element: T | null) => {
      setNode(element);
      const release = assignRef(forwardedRef, element);
      return () => {
        setNode(null);
        release();
      };
    },
    [forwardedRef],
  );
  return [node, ref] as const;
}

"use client";

import { useEffect } from "react";
import {
  createLiquidSpring,
  listen,
  liquidViscosity,
  motionReduced,
  observeMotion,
  rubberBand,
} from "@/lib/liquid/motion";

const properties = [
  "--liquid-x",
  "--liquid-y",
  "--liquid-scale-x",
  "--liquid-scale-y",
  "--liquid-press",
];
const units = ["px", "px", "", "", ""];
// offset x/y, scale x/y, press
const rest = [0, 0, 1, 1, 0];
const clampUnit = (value: number) => Math.max(-1, Math.min(1, value));
// Typing and caret placement in a field inside the glass are not presses of the glass.
const inField = (event: Event) =>
  event.target instanceof Element && !!event.target.closest("input, textarea, [contenteditable]");

/** Small controls grow more than large ones, as on iOS. */
export function swellFor(width: number, height: number) {
  return 1 + Math.max(0.04, Math.min(0.18, 8 / Math.sqrt(Math.max(1, width * height))));
}

/** Scale that swells the glass and stretches it along a rubber-banded drag. */
export function pressedShape(width: number, height: number, drag: number[]) {
  const swell = swellFor(width, height);
  const dx = rubberBand(drag[0], 10);
  const dy = rubberBand(drag[1], 7);
  const sx = Math.abs(dx) / Math.max(1, width);
  const sy = Math.abs(dy) / Math.max(1, height);
  return [dx, dy, swell * (1 + sx * 0.6 - sy * 0.25), swell * (1 + sy * 0.6 - sx * 0.25)];
}

/**
 * Hover attraction, and a press that swells the glass toward the finger and whitens it.
 * Native listeners decorate the element without replacing Radix or consumer handlers.
 */
export class LiquidPress {
  private hover: number[] | null = null;
  private press: { id: number; x: number; y: number } | null = null;
  private drag = [0, 0];
  private keyboard = false;
  private readonly spring;
  private readonly cleanups: (() => void)[] = [];

  constructor(private readonly node: HTMLElement) {
    this.spring = createLiquidSpring(rest, (values) =>
      values.forEach((value, i) => node.style.setProperty(properties[i], `${value}${units[i]}`)),
    );
    const disabledObserver = new MutationObserver(() => this.update());
    disabledObserver.observe(node, {
      attributes: true,
      attributeFilter: ["disabled", "aria-disabled", "data-disabled"],
    });
    this.cleanups.push(
      () => disabledObserver.disconnect(),
      observeMotion(node, () => this.update()),
      listen(node, { pointermove: this.hoverMove, pointerdown: this.down }, { passive: true }),
      listen(node, {
        pointerleave: this.leave,
        keydown: this.keyDown,
        keyup: this.keyUp,
        blur: this.reset,
      }),
      listen(window, { blur: this.reset }),
    );
  }

  /** A springy pop, used when the content morphs. */
  pop() {
    this.spring.kick([0, 0, 2.4, 2.4, 0]);
  }

  destroy() {
    this.spring.stop();
    this.stopTracking();
    this.cleanups.forEach((cleanup) => cleanup());
    properties.forEach((property) => this.node.style.removeProperty(property));
  }

  private disabled() {
    return this.node.matches(':disabled, [aria-disabled="true"], [data-disabled]');
  }

  private target() {
    if (this.press || this.keyboard) {
      const shape = pressedShape(this.node.offsetWidth, this.node.offsetHeight, this.drag);
      return [...shape, 1];
    }
    if (this.hover) return [this.hover[0] * 2, this.hover[1] * 1.5, 1.012, 1.018, 0];
    return rest;
  }

  private update() {
    const still = motionReduced(this.node) || this.disabled();
    this.spring.to(still ? rest : this.target(), still, liquidViscosity(this.node));
  }

  private hoverMove = (event: PointerEvent) => {
    if (event.pointerType === "touch") return;
    const box = this.node.getBoundingClientRect();
    this.hover = [
      clampUnit(((event.clientX - box.left) / box.width) * 2 - 1),
      clampUnit(((event.clientY - box.top) / box.height) * 2 - 1),
    ];
    if (!this.press) this.update();
  };

  private down = (event: PointerEvent) => {
    if (event.button !== 0 || this.disabled() || inField(event)) return;
    this.press = { id: event.pointerId, x: event.clientX, y: event.clientY };
    this.drag = [0, 0];
    this.stopTracking();
    this.stopTracking = listen(window, {
      pointermove: this.track,
      pointerup: this.release,
      pointercancel: this.release,
    });
    this.update();
  };

  private stopTracking = () => {};

  private track = (event: PointerEvent) => {
    if (!this.press || event.pointerId !== this.press.id) return;
    this.drag = [event.clientX - this.press.x, event.clientY - this.press.y];
    this.update();
  };

  private release = (event?: Event) => {
    if (event instanceof PointerEvent && this.press && event.pointerId !== this.press.id) return;
    this.press = null;
    this.drag = [0, 0];
    this.stopTracking();
    this.update();
  };

  private leave = () => {
    this.hover = null;
    if (!this.press) this.update();
  };

  private keyDown = (event: KeyboardEvent) => {
    if (event.key !== " " && event.key !== "Enter") return;
    if (event.repeat || this.disabled() || inField(event)) return;
    this.keyboard = true;
    this.update();
  };

  private keyUp = (event: KeyboardEvent) => {
    if (event.key !== " " && event.key !== "Enter") return;
    this.keyboard = false;
    this.update();
  };

  private reset = () => {
    this.keyboard = false;
    this.hover = null;
    this.release();
  };
}

/** Content morph: springs the width from the old size and lets the new content condense in. */
export class LiquidMorph {
  private width: number;
  private morphing = false;
  private flip = false;
  private readonly sizer;
  private readonly content: MutationObserver;
  private readonly sizes: ResizeObserver;

  constructor(
    private readonly node: HTMLElement,
    private readonly pop: () => void,
  ) {
    this.width = node.offsetWidth;
    this.sizer = createLiquidSpring([this.width], ([value]) => this.resize(value));
    this.content = new MutationObserver(() => this.morph());
    this.content.observe(node, {
      childList: true,
      characterData: true,
      subtree: true,
      attributes: true,
      attributeFilter: ["data-liquid-variant", "aria-pressed"],
    });
    this.sizes = new ResizeObserver(() => {
      if (!this.morphing) this.width = node.offsetWidth;
    });
    this.sizes.observe(node);
  }

  destroy() {
    this.sizer.stop();
    this.content.disconnect();
    this.sizes.disconnect();
    if (this.morphing) this.node.style.removeProperty("width");
    delete this.node.dataset.liquidMorph;
    delete this.node.dataset.liquidMorphing;
  }

  private resize(value: number) {
    if (!this.morphing) return;
    this.node.style.width = `${value}px`;
    if (value !== this.width) return;
    this.morphing = false;
    this.node.style.removeProperty("width");
    delete this.node.dataset.liquidMorphing;
  }

  private morph() {
    const from = this.morphing ? this.node.offsetWidth : this.width;
    if (this.morphing) {
      this.sizer.stop();
      this.morphing = false;
      this.node.style.removeProperty("width");
    }
    // A consumer-owned inline width wins.
    if (this.node.style.width) return;
    this.width = this.node.offsetWidth;
    if (motionReduced(this.node) || this.node.matches(":disabled, [aria-disabled='true']")) return;
    this.flip = !this.flip;
    this.node.dataset.liquidMorph = this.flip ? "a" : "b";
    this.pop();
    if (Math.abs(this.width - from) < 1) return;
    this.morphing = true;
    this.node.dataset.liquidMorphing = "";
    this.sizer.to([from], true);
    this.sizer.to([this.width], false, liquidViscosity(this.node));
  }
}

/** Press, hover attraction, and content morph for one glass control. */
export function useLiquidInteraction(node: HTMLElement | null) {
  useEffect(() => {
    if (!node) return;
    const press = new LiquidPress(node);
    const morph = new LiquidMorph(node, () => press.pop());
    return () => {
      morph.destroy();
      press.destroy();
    };
  }, [node]);
}

"use client";

import { useEffect } from "react";
import {
  createLiquidSpring,
  listen,
  liquidViscosity,
  motionReduced,
  observeMotion,
} from "@/lib/liquid/motion";
import {
  activate,
  boxWithin,
  followBox,
  lensFrame,
  lensMask,
  mirror,
  nearestBox,
  pointerWithin,
  type Box,
} from "@/lib/liquid/lens-parts";

export type LensOptions = {
  /** Matches the selected item, e.g. `.liquid-tab[data-state="active"]`. */
  selected: string;
  /** Matches every item the lens can land on. */
  items: string;
  /** Let a press drag the lens across items and select where it is released. */
  scrub?: boolean;
};

const inactive = ':disabled, [data-disabled], [aria-disabled="true"]';
const watched = ["data-state", "aria-pressed", "data-orientation", "aria-orientation", "dir"];

/**
 * One continuous glass lens. It lifts while pressed or travelling, magnifies and tints what is
 * beneath it, then lands and frosts over the selection. The lens shows an inert, aria-hidden
 * copy of the list; the real items stay untouched for Radix and assistive technology.
 */
export class LiquidLens {
  private readonly lens = document.createElement("span");
  private readonly optics = document.createElement("span");
  private readonly spring;
  private readonly masked = new Set<HTMLElement>();
  private readonly cleanups: (() => void)[] = [];
  private readonly resize = new ResizeObserver(() => this.measure());
  private elements: HTMLElement[] = [];
  private boxes = new Map<HTMLElement, Box>();
  private current: HTMLElement | null = null;
  private goal: Box = [0, 0, 0, 0];
  private follow: Box | null = null;
  private press: { id: number; x: number; y: number; dragging: boolean } | null = null;
  private travelling = false;
  private initialized = false;
  private reduced = false;
  private vertical = false;
  private border = [0, 0];

  constructor(
    private readonly node: HTMLElement,
    private readonly options: LensOptions,
  ) {
    this.lens.className = "liquid-lens";
    this.lens.setAttribute("aria-hidden", "true");
    this.lens.setAttribute("inert", "");
    this.lens.append(this.optics);
    node.append(this.lens);
    this.spring = createLiquidSpring([0, 0, 0, 0, 0], (values, velocity) =>
      this.render(values, velocity),
    );
    const mutations = new MutationObserver((records) => this.mutated(records));
    mutations.observe(node, {
      subtree: true,
      childList: true,
      characterData: true,
      attributes: true,
      attributeFilter: [...watched, "class", "disabled", "data-disabled"],
    });
    this.cleanups.push(
      () => mutations.disconnect(),
      () => this.resize.disconnect(),
      observeMotion(node, () => this.motionChanged()),
      listen(node, { pointerdown: this.down }, { passive: true }),
    );
    this.refresh();
    this.measure();
  }

  destroy() {
    this.spring.stop();
    this.endPress();
    this.unmask();
    this.cleanups.forEach((cleanup) => cleanup());
    this.lens.remove();
    delete this.node.dataset.liquidIndicator;
    delete this.node.dataset.liquidLens;
    this.node.style.removeProperty("--liquid-lift");
  }

  private render([x, y, w, h, lift]: number[], velocity: number[]) {
    this.landIfArrived(x, y);
    const speed = this.reduced ? 0 : velocity[this.vertical ? 1 : 0];
    const frame = lensFrame([x, y, w, h], lift, speed, this.vertical);
    const [left, top, width, height] = frame;
    const lifted = Math.max(0, lift);
    const [bx, by] = this.border;
    this.lens.style.width = `${width}px`;
    this.lens.style.height = `${height}px`;
    this.lens.style.transform = `translate(${left}px, ${top}px)`;
    this.optics.style.transformOrigin = `${x + w / 2 + bx}px ${y + h / 2 + by}px`;
    this.optics.style.transform = `translate(${-left - bx}px, ${-top - by}px) scale(${1 + 0.12 * lifted})`;
    this.node.style.setProperty("--liquid-lift", lifted.toFixed(3));
    const resting = this.isResting([x, y, w, h], lifted);
    this.node.dataset.liquidLens = resting ? "rest" : "active";
    if (resting) this.unmask();
    else this.mask(frame);
  }

  private landIfArrived(x: number, y: number) {
    if (!this.travelling || this.press) return;
    const reach = Math.max(6, this.goal[this.vertical ? 3 : 2] * 0.15);
    if (Math.hypot(x - this.goal[0], y - this.goal[1]) >= reach) return;
    this.travelling = false;
    this.commit();
  }

  private isResting(box: Box, lifted: number) {
    if (this.press || this.travelling || lifted >= 0.005) return false;
    return box.every((value, i) => Math.abs(value - this.goal[i]) < 0.5);
  }

  private commit(immediate = false) {
    const lifted = !this.reduced && (this.press !== null || this.travelling) ? 1 : 0;
    const feel = liquidViscosity(this.node);
    this.spring.to([...(this.follow ?? this.goal), lifted], immediate || this.reduced, feel);
  }

  // Hide the real items where the lens sits, so only the magnified copy shows through it.
  private mask(frame: Box) {
    for (const element of this.elements) {
      const image = lensMask(this.boxes.get(element) ?? [0, 0, 0, 0], frame, this.vertical);
      if (image) {
        element.style.setProperty("mask-image", image);
        element.style.setProperty("-webkit-mask-image", image);
        this.masked.add(element);
      } else if (this.masked.delete(element)) this.clearMask(element);
    }
  }

  private unmask() {
    this.masked.forEach((element) => this.clearMask(element));
    this.masked.clear();
  }

  private clearMask(element: HTMLElement) {
    element.style.removeProperty("mask-image");
    element.style.removeProperty("-webkit-mask-image");
  }

  private mutated(records: MutationRecord[]) {
    const relevant = records.filter((record) => !this.lens.contains(record.target));
    if (!relevant.length) return;
    this.refresh();
    this.measure();
  }

  private refresh() {
    const { node, lens, optics } = this;
    this.elements = [...node.querySelectorAll<HTMLElement>(this.options.items)].filter(
      (element) => !lens.contains(element),
    );
    this.resize.disconnect();
    [node, ...this.elements].forEach((element) => this.resize.observe(element));
    mirror(node, lens, optics);
  }

  private measure() {
    const { node } = this;
    this.reduced = motionReduced(node);
    const orientation = node.getAttribute("aria-orientation") ?? node.dataset.orientation;
    this.vertical = orientation === "vertical";
    this.border = [node.clientLeft, node.clientTop];
    this.boxes = new Map(this.elements.map((element) => [element, boxWithin(element, node)]));
    this.optics.style.width = `${node.offsetWidth}px`;
    this.optics.style.height = `${node.offsetHeight}px`;
    const next = this.elements.find((element) => element.matches(this.options.selected));
    if (next) this.place(next);
    else this.hide();
  }

  private place(next: HTMLElement) {
    const geometry = this.boxes.get(next)!;
    const moved = this.initialized && next !== this.current;
    const resized = geometry.some((value, i) => value !== this.goal[i]);
    if (this.initialized && !moved && !resized) return;
    this.goal = geometry;
    this.current = next;
    this.node.dataset.liquidIndicator = "true";
    if (!this.initialized || this.reduced) {
      this.travelling = false;
      this.commit(true);
    } else if (moved) {
      this.travelling = true;
      this.commit();
    } else this.commit(!this.press);
    this.initialized = true;
  }

  private hide() {
    this.current = null;
    this.initialized = false;
    this.travelling = false;
    delete this.node.dataset.liquidIndicator;
    delete this.node.dataset.liquidLens;
    this.unmask();
  }

  private motionChanged() {
    this.reduced = motionReduced(this.node);
    if (this.initialized) this.commit(true);
  }

  private enabled() {
    return this.elements.filter((element) => !element.matches(inactive));
  }

  private nearest(position: number) {
    const candidates = this.enabled();
    const boxes = candidates.map((element) => this.boxes.get(element)!);
    return candidates[nearestBox(boxes, position, this.vertical)] ?? null;
  }

  private down = (event: PointerEvent) => {
    if (event.button !== 0 || this.reduced || !this.current) return;
    const item = event.target instanceof Element ? event.target.closest(this.options.items) : null;
    if (!(item instanceof HTMLElement) || !this.elements.includes(item) || item.matches(inactive))
      return;
    this.press = { id: event.pointerId, x: event.clientX, y: event.clientY, dragging: false };
    this.node.dataset.liquidPressed = "true";
    this.stopTracking = listen(window, {
      pointermove: this.move,
      pointerup: this.up,
      pointercancel: this.up,
    });
    this.commit();
  };

  private stopTracking = () => {};

  private move = (event: PointerEvent) => {
    const { press } = this;
    if (!this.options.scrub || !press || event.pointerId !== press.id) return;
    const distance = Math.hypot(event.clientX - press.x, event.clientY - press.y);
    if (!press.dragging && distance < 6) return;
    press.dragging = true;
    const position = pointerWithin(event, this.node, this.border, this.vertical);
    const under = this.nearest(position);
    if (!under) return;
    const boxes = this.enabled().map((element) => this.boxes.get(element)!);
    this.follow = followBox(boxes, this.boxes.get(under)!, position, this.vertical);
    this.commit();
  };

  private up = (event: PointerEvent) => {
    if (!this.press || event.pointerId !== this.press.id) return;
    const landing = this.landingFor(event);
    this.endPress();
    if (landing && landing !== this.current) activate(landing, this.node);
    this.commit();
  };

  private landingFor(event: PointerEvent) {
    const { follow, vertical } = this;
    if (!this.press?.dragging || !follow || event.type !== "pointerup") return null;
    const axis = vertical ? 1 : 0;
    return this.nearest(follow[axis] + follow[axis + 2] / 2);
  }

  private endPress() {
    this.press = null;
    this.follow = null;
    delete this.node.dataset.liquidPressed;
    this.stopTracking();
  }
}

/** Attach a lens to a tab list or toolbar. */
export function useLiquidIndicator(node: HTMLElement | null, options: LensOptions) {
  const { selected, items, scrub } = options;
  useEffect(() => {
    if (!node) return;
    const lens = new LiquidLens(node, { selected, items, scrub });
    return () => lens.destroy();
  }, [node, selected, items, scrub]);
}

import { rubberBand } from "@/lib/liquid/motion";

// Geometry and DOM helpers for the lens in lens.ts.

/** x, y, width, height in a list's padding-box coordinates. */
export type Box = [number, number, number, number];

/** Layout position of `element` inside `root`, unaffected by CSS transforms. */
export function boxWithin(element: HTMLElement, root: HTMLElement): Box {
  let x = 0;
  let y = 0;
  for (let at: HTMLElement | null = element; at && at !== root;) {
    x += at.offsetLeft;
    y += at.offsetTop;
    const parent = at.offsetParent as HTMLElement | null;
    if (!parent || !root.contains(parent)) break;
    if (parent !== root) {
      x += parent.clientLeft;
      y += parent.clientTop;
    }
    at = parent;
  }
  return [x, y, element.offsetWidth, element.offsetHeight];
}

/**
 * Visual frame of the lens for a spring state. Lifting grows it, more across the list than
 * along it; speed stretches it along the direction of travel.
 */
export function lensFrame(box: Box, lift: number, speed: number, vertical: boolean): Box {
  const [x, y, w, h] = box;
  const lifted = Math.max(0, lift);
  const stretch = Math.min(0.24, Math.abs(speed) / 5200);
  const along = (1 + 0.16 * lifted) * (1 + stretch);
  const across = (1 + 0.34 * lifted) * (1 - stretch * 0.3);
  const width = w * (vertical ? across : along);
  const height = h * (vertical ? along : across);
  return [x + w / 2 - width / 2, y + h / 2 - height / 2, width, height];
}

/** A mask that hides the part of an item under the lens, or null when they do not overlap. */
export function lensMask(item: Box, frame: Box, vertical: boolean) {
  const axis = vertical ? 1 : 0;
  const start = frame[axis] - item[axis];
  const end = start + frame[axis + 2];
  if (end <= 0 || start >= item[axis + 2]) return null;
  const soft = Math.min(8, (end - start) / 4);
  return `linear-gradient(${vertical ? 180 : 90}deg, #000 ${start}px, transparent ${start + soft}px, transparent ${end - soft}px, #000 ${end}px)`;
}

/** Index of the box whose center is nearest `position` along the list's axis. */
export function nearestBox(boxes: Box[], position: number, vertical: boolean) {
  const axis = vertical ? 1 : 0;
  let best = -1;
  let distance = Infinity;
  boxes.forEach((box, i) => {
    const gap = Math.abs(box[axis] + box[axis + 2] / 2 - position);
    if (gap < distance) {
      distance = gap;
      best = i;
    }
  });
  return best;
}

/** Lens box centered on the finger, rubber-banded past the first and last items. */
export function followBox(boxes: Box[], under: Box, position: number, vertical: boolean): Box {
  const axis = vertical ? 1 : 0;
  const size = under[axis + 2];
  const min = Math.min(...boxes.map((box) => box[axis]));
  const max = Math.max(...boxes.map((box) => box[axis] + box[axis + 2])) - size;
  let start = position - size / 2;
  if (start < min) start = min - rubberBand(min - start, 14);
  else if (start > max) start = max + rubberBand(start - max, 14);
  const next: Box = [...under];
  next[axis] = start;
  return next;
}

/** Pointer position along the list's axis, in padding-box coordinates, undoing its scale. */
export function pointerWithin(
  event: PointerEvent,
  list: HTMLElement,
  border: number[],
  vertical: boolean,
) {
  const bounds = list.getBoundingClientRect();
  if (vertical)
    return (event.clientY - bounds.top) / (bounds.height / (list.offsetHeight || 1)) - border[1];
  return (event.clientX - bounds.left) / (bounds.width / (list.offsetWidth || 1)) - border[0];
}

/** Refresh the optics: an inert copy of the list with its classes, minus the lens itself. */
export function mirror(list: HTMLElement, lens: HTMLElement, optics: HTMLElement) {
  optics.className = `${list.className} liquid-lens-optics`;
  for (const name of ["dir", "data-orientation", "data-variant"]) {
    const value = list.getAttribute(name);
    if (value === null) optics.removeAttribute(name);
    else optics.setAttribute(name, value);
  }
  const children = [...list.children].filter((child) => child !== lens);
  optics.replaceChildren(...children.map(copyOf));
}

/** An inert copy of a list child for the lens: no ids, no lens masks. */
function copyOf(child: Element) {
  const copy = child.cloneNode(true) as HTMLElement;
  for (const element of [copy, ...copy.querySelectorAll<HTMLElement>("*")]) {
    element.removeAttribute("id");
    element.style?.removeProperty("mask-image");
    element.style?.removeProperty("-webkit-mask-image");
  }
  return copy;
}

/** Radix tabs select on mousedown; focus keeps the roving tab stop in sync. */
export function activate(element: HTMLElement, list: HTMLElement) {
  const init = { bubbles: true, cancelable: true, button: 0, view: window };
  element.dispatchEvent(new MouseEvent("mousedown", init));
  if (list.contains(document.activeElement)) element.focus({ preventScroll: true });
}

import { listen } from "@/lib/liquid/motion";

// The neck that forms where two separate glass surfaces flow into each other: the tab bar
// bulging into its search button, or a closing menu drawn back into its trigger.

export type Point = [number, number];
/** A round end of a surface: center x, center y, radius. */
export type Cap = [number, number, number];
type Rect = Pick<DOMRect, "left" | "top" | "width" | "height">;

const HALF_PI = Math.PI / 2;
const at = ([x, y]: Point, angle: number, length: number): Point => [
  x + length * Math.cos(angle),
  y + length * Math.sin(angle),
];

/**
 * The rounded corner (or end) of a surface nearest `toward`: a circle of the surface's corner
 * radius, as close to `toward` as the surface allows. A capsule's ends are circles as tall as
 * it is; a panel's flat edge is met by a circle the size of its corners, just inside it.
 */
export function capOf(rect: Rect, toward: Point, corner = Infinity): Cap {
  const radius = Math.max(0, Math.min(corner, rect.width / 2, rect.height / 2));
  const clamp = (value: number, start: number, size: number) =>
    Math.max(start + radius, Math.min(start + size - radius, value));
  return [clamp(toward[0], rect.left, rect.width), clamp(toward[1], rect.top, rect.height), radius];
}

/** Left, top, right, bottom of two caps together. */
export function capBounds([ax, ay, ra]: Cap, [bx, by, rb]: Cap) {
  return [
    Math.min(ax - ra, bx - rb),
    Math.min(ay - ra, by - rb),
    Math.max(ax + ra, bx + rb),
    Math.max(ay + ra, by + rb),
  ] as const;
}

/**
 * Spread of the neck, clamped to 0–1. It narrows as one circle sinks into the other, since a
 * deep overlap leaves only a sliver of neck and the drop reads as merging, and it is 0 once
 * one circle contains the other.
 */
export function spreadAt(d: number, ra: number, rb: number, spread: number) {
  const inner = Math.abs(ra - rb);
  const depth = d >= ra + rb ? 1 : (d - inner) / Math.max(1e-6, ra + rb - inner);
  return Math.max(0, Math.min(1, spread)) * Math.max(0, Math.min(1, depth * 1.4));
}

export type Neck = {
  /** Closed outline of the neck, for a clip path. */
  outline: string;
  /** Its two free edges, where the glass rim catches the light. */
  rims: string;
};

/**
 * The neck between two circles, after the classic metaball construction: two curves leave the
 * first circle, meet the second tangentially, and close along each circle's near side, so the
 * neck fills only the space between the surfaces and never tints them twice. `spread` (0–1)
 * sets how far round each circle the neck reaches; 0 is no neck. Coordinates are written
 * relative to `origin`. Returns null when the circles are too far apart or one contains the other.
 */
export function neckBetween(a: Cap, b: Cap, spread: number, origin: Point = [0, 0]): Neck | null {
  const [ax, ay, ra] = a;
  const [bx, by, rb] = b;
  const d = Math.hypot(bx - ax, by - ay);
  const overlap = d < ra + rb;
  const v = spreadAt(d, ra, rb, spread);
  if (v < 0.01 || !ra || !rb || d > ra + rb * 2.5) return null;
  const ua = overlap ? Math.acos((ra * ra + d * d - rb * rb) / (2 * ra * d)) : 0;
  const ub = overlap ? Math.acos((rb * rb + d * d - ra * ra) / (2 * rb * d)) : 0;
  const toward = Math.atan2(by - ay, bx - ax);
  const maxSpread = Math.acos((ra - rb) / d);
  const halfA = ua + (maxSpread - ua) * v;
  const halfB = ub + (Math.PI - ub - maxSpread) * v;
  const p1 = at([ax, ay], toward + halfA, ra);
  const p2 = at([ax, ay], toward - halfA, ra);
  const p3 = at([bx, by], toward + Math.PI - halfB, rb);
  const p4 = at([bx, by], toward + Math.PI + halfB, rb);
  const reach = Math.min(v * 2.4, Math.hypot(p3[0] - p1[0], p3[1] - p1[1]) / (ra + rb));
  const handle = reach * Math.min(1, (d * 2) / (ra + rb));
  const h1 = at(p1, toward + halfA - HALF_PI, ra * handle);
  const h2 = at(p2, toward - halfA + HALF_PI, ra * handle);
  const h3 = at(p3, toward + Math.PI - halfB + HALF_PI, rb * handle);
  const h4 = at(p4, toward + Math.PI + halfB - HALF_PI, rb * handle);
  const pt = ([x, y]: Point) => `${(x - origin[0]).toFixed(2)} ${(y - origin[1]).toFixed(2)}`;
  // Along each circle's near side, in the direction of increasing angle (clockwise on screen).
  const arc = (r: number, half: number, to: Point) =>
    `A ${r.toFixed(2)} ${r.toFixed(2)} 0 ${half * 2 > Math.PI ? 1 : 0} 1 ${pt(to)}`;
  const lower = `M ${pt(p1)} C ${pt(h1)} ${pt(h3)} ${pt(p3)}`;
  const upper = `C ${pt(h4)} ${pt(h2)} ${pt(p2)}`;
  return {
    outline: `${lower} ${arc(rb, halfB, p4)} ${upper} ${arc(ra, halfA, p1)} Z`,
    // Overlapping, the edges run over the surfaces' own rims.
    rims: overlap ? "" : `${lower} M ${pt(p4)} ${upper}`,
  };
}

const svgNS = "http://www.w3.org/2000/svg";

/**
 * A computed `border-*-radius` in px for a box, including the `calc(a% + bpx)` values that
 * animations produce and separate horizontal and vertical radii. Returns the smaller radius.
 */
export function parseRadius(value: string, width: number, height: number) {
  const parts = value.match(/calc\([^)]*\)|\S+/g) ?? [];
  if (!parts.length) return 0;
  const pair = parts.length > 1 ? parts.slice(0, 2) : [parts[0], parts[0]];
  const [rx, ry] = pair.map((part = "", axis) => {
    let total = 0;
    for (const [, sign, number, unit] of part.matchAll(/([+-]\s*)?(\d*\.?\d+(?:e-?\d+)?)(px|%)/g)) {
      const size = unit === "%" ? (Number(number) / 100) * (axis ? height : width) : Number(number);
      total += sign?.trim() === "-" ? -size : size;
    }
    return total;
  });
  return Math.max(0, Math.min(rx, ry));
}

/** An element's corner radius as drawn: its computed radius, scaled with any transform. */
function drawnRadius(element: HTMLElement, box: Rect) {
  const width = element.offsetWidth || box.width;
  const height = element.offsetHeight || box.height;
  const radius = parseRadius(getComputedStyle(element).borderTopLeftRadius, width, height);
  return radius * Math.min(box.width / (width || 1), box.height / (height || 1));
}

/**
 * Draws the neck between two surfaces as a glass element clipped to the neck's outline. The
 * element lives in `container` (positioned), or in a fixed layer over the viewport when the
 * surfaces are in different stacking contexts, such as a portaled menu and its trigger.
 */
export class LiquidFusion {
  readonly element = document.createElement("span");
  private readonly rim = document.createElementNS(svgNS, "path");

  constructor(
    private readonly a: HTMLElement,
    private readonly b: HTMLElement,
    private readonly container: HTMLElement | null = null,
  ) {
    this.element.className = "liquid-fusion";
    this.element.setAttribute("aria-hidden", "true");
    this.element.hidden = true;
    if (!container) this.element.dataset.layer = "fixed";
    const svg = document.createElementNS(svgNS, "svg");
    svg.append(this.rim);
    this.element.append(svg);
    (container ?? document.body).append(this.element);
  }

  /** Match the glass of `source`: its fill and its blur. A refraction map fits only its owner. */
  paint(source: HTMLElement) {
    const style = getComputedStyle(source);
    const backdrop = (style.backdropFilter || "none").replace(/url\([^)]*\)\s*/g, "").trim();
    this.element.style.backgroundColor = style.backgroundColor;
    this.element.style.setProperty("backdrop-filter", backdrop || "none");
    this.element.style.setProperty("-webkit-backdrop-filter", backdrop || "none");
  }

  /** Redraw at `strength` (0–1). Returns whether a neck is showing. */
  draw(strength: number, opacity = 1) {
    const boxA = this.a.getBoundingClientRect();
    const boxB = this.b.getBoundingClientRect();
    const centerB: Point = [boxB.left + boxB.width / 2, boxB.top + boxB.height / 2];
    const capA = capOf(boxA, centerB, drawnRadius(this.a, boxA));
    const capB = capOf(boxB, [capA[0], capA[1]], drawnRadius(this.b, boxB));
    const [left, top, right, bottom] = capBounds(capA, capB);
    const neck = strength > 0 ? neckBetween(capA, capB, strength, [left, top]) : null;
    this.element.hidden = !neck;
    if (!neck) return false;
    const [x, y] = this.origin();
    Object.assign(this.element.style, {
      left: `${left - x}px`,
      top: `${top - y}px`,
      width: `${right - left}px`,
      height: `${bottom - top}px`,
      opacity: String(opacity),
      clipPath: `path("${neck.outline}")`,
    });
    this.rim.setAttribute("d", neck.rims);
    return true;
  }

  destroy() {
    this.element.remove();
  }

  private origin(): Point {
    if (!this.container) return [0, 0];
    const box = this.container.getBoundingClientRect();
    return [box.left + this.container.clientLeft, box.top + this.container.clientTop];
  }
}

export type FusionSample = { strength: number; opacity?: number; hold?: boolean };

/**
 * Redraws a fusion every frame while `sample` reports a neck, a hold, or a press on one of
 * the surfaces, then stops. `wake` restarts it.
 */
export class FusionLoop {
  private frame = 0;
  private held = false;
  private readonly cleanups: (() => void)[] = [];

  constructor(
    private readonly fusion: LiquidFusion,
    private readonly sample: () => FusionSample,
  ) {}

  /** Draw while a press that began inside one of these elements lasts. */
  wakeOn(...elements: HTMLElement[]) {
    const release = () => {
      this.held = false;
    };
    const press = () => {
      this.held = true;
      this.wake();
    };
    for (const element of elements) {
      this.cleanups.push(listen(element, { pointerdown: press }, { passive: true }));
    }
    this.cleanups.push(
      listen(window, { pointerup: release, pointercancel: release, blur: release }),
    );
    return this;
  }

  wake = () => {
    if (!this.frame) this.frame = requestAnimationFrame(this.tick);
  };

  destroy() {
    cancelAnimationFrame(this.frame);
    this.frame = 0;
    this.cleanups.forEach((cleanup) => cleanup());
    this.fusion.destroy();
  }

  private tick = () => {
    this.frame = 0;
    const { strength, opacity = 1, hold = false } = this.sample();
    const showing = this.fusion.draw(strength, opacity);
    if (showing || hold || this.held) this.wake();
  };
}

"use client";

import { useEffect } from "react";

// Refraction of the page behind the glass. The rim of a glass surface is a curved bezel, so it
// bends what is behind it: near the edge, the backdrop is drawn from further inside. An SVG
// displacement map encodes that bend and `backdrop-filter: url(#…)` applies it to the backdrop.
// Only Chromium renders SVG filters in `backdrop-filter`, so elsewhere the glass keeps its blur.

/** Width of the bending rim in px, capped by the corner radius. */
export const bezelFor = (radius: number) => Math.max(4, Math.min(radius, 18));
/** Deepest displacement at the very edge, in px. */
export const refractionDepth = (bezel: number) => Math.round(bezel * 0.6);

/**
 * Distance of a point from the edge of a rounded rectangle (positive inside) and the edge's
 * outward normal there.
 */
export function edgeOf(x: number, y: number, width: number, height: number, radius: number) {
  const r = Math.min(radius, width / 2, height / 2);
  const dx = x - width / 2;
  const dy = y - height / 2;
  const qx = Math.abs(dx) - (width / 2 - r);
  const qy = Math.abs(dy) - (height / 2 - r);
  if (qx > 0 && qy > 0) {
    const length = Math.hypot(qx, qy);
    return {
      distance: r - length,
      nx: (Math.sign(dx) * qx) / length,
      ny: (Math.sign(dy) * qy) / length,
    };
  }
  if (qx > qy) return { distance: r - qx, nx: Math.sign(dx) || 1, ny: 0 };
  return { distance: r - qy, nx: 0, ny: Math.sign(dy) || 1 };
}

/**
 * RGBA displacement map for a rounded rectangle: red and green are x and y offsets around 128.
 * Inside the bezel, points are displaced inward along the normal, most strongly at the edge
 * and easing to nothing where the bezel meets the flat face.
 */
export function displacementMap(width: number, height: number, radius: number) {
  const w = Math.max(1, Math.round(width));
  const h = Math.max(1, Math.round(height));
  const bezel = bezelFor(Math.min(radius, w / 2, h / 2));
  const data = new Uint8ClampedArray(w * h * 4).fill(128);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = (y * w + x) * 4;
      data[i + 3] = 255;
      const { distance, nx, ny } = edgeOf(x + 0.5, y + 0.5, w, h, radius);
      if (distance >= bezel) continue;
      const t = 1 - Math.max(0, distance) / bezel;
      const strength = t * t * 127;
      data[i] = 128 - nx * strength;
      data[i + 1] = 128 - ny * strength;
    }
  }
  return { data, width: w, height: h, scale: refractionDepth(bezel) * 2 };
}

type UAData = { brands?: { brand: string }[] };

/** SVG filters in `backdrop-filter` render only in Chromium; elsewhere they drop the blur too. */
export function refractionSupported() {
  if (typeof CSS === "undefined" || typeof navigator === "undefined") return false;
  const brands = (navigator as Navigator & { userAgentData?: UAData }).userAgentData?.brands;
  return (
    !!brands?.some(({ brand }) => brand === "Chromium") &&
    CSS.supports("backdrop-filter", "url(#liquid) blur(1px)")
  );
}

const svgNS = "http://www.w3.org/2000/svg";
let count = 0;

function definitions() {
  const existing = document.getElementById("liquid-refraction-defs");
  if (existing) return existing;
  const svg = document.createElementNS(svgNS, "svg");
  svg.id = "liquid-refraction-defs";
  svg.setAttribute("aria-hidden", "true");
  svg.setAttribute("width", "0");
  svg.setAttribute("height", "0");
  svg.style.position = "absolute";
  document.body.append(svg);
  return svg;
}

function element(name: string, attributes: Record<string, string>) {
  const node = document.createElementNS(svgNS, name);
  Object.entries(attributes).forEach(([key, value]) => node.setAttribute(key, value));
  return node;
}

/** Bends the backdrop at the rim of one glass surface. Does nothing where unsupported. */
export class LiquidRefraction {
  private readonly id = `liquid-refraction-${++count}`;
  private readonly filter = element("filter", {
    x: "0",
    y: "0",
    filterUnits: "userSpaceOnUse",
    primitiveUnits: "userSpaceOnUse",
    "color-interpolation-filters": "sRGB",
  });
  private readonly map = element("feImage", {
    x: "0",
    y: "0",
    preserveAspectRatio: "none",
    result: "map",
  });
  private readonly bend = element("feDisplacementMap", {
    in: "SourceGraphic",
    in2: "map",
    xChannelSelector: "R",
    yChannelSelector: "G",
  });
  private readonly resize = new ResizeObserver(() => this.resized());
  private timer = 0;
  private drawn = "";

  constructor(private readonly node: HTMLElement) {
    this.filter.id = this.id;
    this.filter.append(this.map, this.bend);
    definitions().append(this.filter);
    this.resize.observe(node);
    this.resized();
    this.redraw();
    node.style.setProperty("--liquid-refraction", `url(#${this.id})`);
    node.dataset.liquidRefraction = "";
  }

  destroy() {
    clearTimeout(this.timer);
    this.resize.disconnect();
    this.filter.remove();
    const defs = document.getElementById("liquid-refraction-defs");
    if (defs && !defs.childElementCount) defs.remove();
    this.node.style.removeProperty("--liquid-refraction");
    delete this.node.dataset.liquidRefraction;
  }

  // The last map stretches to the new size at once; a fresh one follows when resizing pauses.
  private resized() {
    const { offsetWidth: width, offsetHeight: height } = this.node;
    for (const target of [this.filter, this.map]) {
      target.setAttribute("width", String(width));
      target.setAttribute("height", String(height));
    }
    clearTimeout(this.timer);
    this.timer = window.setTimeout(() => this.redraw(), 120);
  }

  private redraw() {
    const { offsetWidth: width, offsetHeight: height } = this.node;
    const radius = parseFloat(getComputedStyle(this.node).borderTopLeftRadius) || 0;
    const key = `${width}x${height}@${radius}`;
    if (!width || !height || key === this.drawn) return;
    const map = displacementMap(width, height, radius);
    const canvas = document.createElement("canvas");
    canvas.width = map.width;
    canvas.height = map.height;
    const context = canvas.getContext("2d");
    if (!context) return;
    context.putImageData(new ImageData(map.data, map.width, map.height), 0, 0);
    this.map.setAttribute("href", canvas.toDataURL());
    this.bend.setAttribute("scale", String(map.scale));
    this.drawn = key;
  }
}

/** Refract the backdrop at the rim of a glass surface, in browsers that can. */
export function useLiquidRefraction(node: HTMLElement | null) {
  useEffect(() => {
    if (!node || !refractionSupported()) return;
    const refraction = new LiquidRefraction(node);
    return () => refraction.destroy();
  }, [node]);
}

"use client";

import { useLayoutEffect, useRef } from "react";
import { FusionLoop, LiquidFusion } from "@/lib/liquid/fusion";
import { createLiquidSpring, listen, liquidViscosity, motionReduced } from "@/lib/liquid/motion";
import { LiquidPress } from "@/lib/liquid/press";

const numberOf = (element: HTMLElement | null, property: string) =>
  parseFloat(element?.style.getPropertyValue(property) ?? "") || 0;

/**
 * How strongly the tab bar and its search button fuse: pressing the button swells it into the
 * bar, and lifting the lens on the bar swells the bar into the button.
 */
export function fusionStrength(searchPress: number, barLift: number) {
  return Math.max(0, Math.min(1, Math.max(searchPress * 0.5, barLift * 0.32)));
}

/**
 * The search morph. Entering search collapses the tab bar into a circle and stretches the
 * search button into a field; leaving reverses it. CSS lays out both states. This springs the
 * width of each part from where it was to where the new layout puts it, so any layout works.
 */
export class TabBarMorph {
  private readonly items: HTMLElement | null;
  private readonly search: HTMLElement | null;
  private readonly press: LiquidPress | null = null;
  private readonly fusion: FusionLoop | null = null;
  private readonly spring;
  private readonly sizes = new ResizeObserver(() => this.measure());
  private readonly cleanups: (() => void)[] = [];
  private resting = [0, 0];
  private target = [0, 0];
  private morphing = false;

  constructor(private readonly root: HTMLElement) {
    this.items = root.querySelector<HTMLElement>(":scope > .liquid-tab-bar-items");
    this.search = root.querySelector<HTMLElement>(":scope > .liquid-tab-bar-search");
    this.spring = createLiquidSpring([0, 0], (values) => this.render(values));
    if (this.search) this.press = new LiquidPress(this.search);
    if (this.items && this.search) this.fusion = this.fuse(this.items, this.search);
    for (const element of [root, this.items, this.search]) if (element) this.sizes.observe(element);
    this.measure();
  }

  /** Call once the DOM shows the new state, before paint. */
  toggle() {
    const { items, search, root } = this;
    if (!items || !search) return;
    const from = this.morphing ? [items.offsetWidth, search.offsetWidth] : this.resting;
    this.settle();
    const to = [items.offsetWidth, search.offsetWidth];
    this.resting = to;
    if (motionReduced(root) || from.every((width, i) => Math.abs(width - to[i]) < 1)) return;
    this.morphing = true;
    this.target = to;
    root.dataset.liquidMorphing = "";
    this.spring.to(from, true);
    this.spring.to(to, false, liquidViscosity(root));
    this.press?.pop();
  }

  destroy() {
    this.settle();
    this.sizes.disconnect();
    this.press?.destroy();
    this.fusion?.destroy();
    this.cleanups.forEach((cleanup) => cleanup());
    this.root.style.removeProperty("--liquid-tab-bar-circle");
    this.root.style.removeProperty("--liquid-tab-bar-width");
  }

  private fuse(items: HTMLElement, search: HTMLElement) {
    const fusion = new LiquidFusion(items, search, this.root);
    const strength = () => {
      if (motionReduced(this.root) || this.morphing) return 0;
      const list = items.querySelector<HTMLElement>("[data-liquid-indicator]");
      return fusionStrength(numberOf(search, "--liquid-press"), numberOf(list, "--liquid-lift"));
    };
    // Repaint before each press, so the neck follows theme and material changes.
    const paint = () => fusion.paint(items);
    this.cleanups.push(listen(this.root, { pointerdown: paint }, { capture: true }));
    return new FusionLoop(fusion, () => ({ strength: strength() })).wakeOn(items, search);
  }

  // Remember the resting layout, so the next toggle knows where the morph starts.
  private measure() {
    const { root, items, search } = this;
    if (!items || !search) return;
    // Hidden tabs (say, on a phone) leave the circle size to CSS.
    const circle = items.offsetHeight;
    if (circle) root.style.setProperty("--liquid-tab-bar-circle", `${circle}px`);
    else root.style.removeProperty("--liquid-tab-bar-circle");
    if (this.morphing) return;
    this.resting = [items.offsetWidth, search.offsetWidth];
    if (!root.hasAttribute("data-searching"))
      root.style.setProperty("--liquid-tab-bar-width", `${root.offsetWidth}px`);
  }

  private render([items, search]: number[]) {
    if (!this.morphing || !this.items || !this.search) return;
    this.items.style.width = `${items}px`;
    this.search.style.width = `${search}px`;
    if (items === this.target[0] && search === this.target[1]) this.settle();
  }

  private settle() {
    this.spring.stop();
    this.morphing = false;
    this.items?.style.removeProperty("width");
    this.search?.style.removeProperty("width");
    delete this.root.dataset.liquidMorphing;
  }
}

/** Attach the search morph, fusion, and search button press to a tab bar. */
export function useTabBarMorph(node: HTMLElement | null, searching: boolean) {
  const morph = useRef<TabBarMorph | null>(null);
  useLayoutEffect(() => {
    if (!node) return;
    const instance = new TabBarMorph(node);
    morph.current = instance;
    return () => {
      instance.destroy();
      morph.current = null;
    };
  }, [node]);
  useLayoutEffect(() => {
    morph.current?.toggle();
  }, [searching]);
}
